<script setup lang="ts">import {computed} from 'vue';import type {Finding} from '../types/domain';import {shortNames} from '../constants/enums';import {number} from '../utils/format';const props=defineProps<{findings:Finding[]}>();const sorted=computed(()=>[...props.findings].sort((a,b)=>b.importance_mean-a.importance_mean));const range=computed(()=>{const lo=Math.min(0,...props.findings.map(f=>f.importance_low)),hi=Math.max(1,...props.findings.map(f=>f.importance_high));const pad=(hi-lo)*.08;return [lo-pad,hi+pad];});const sx=(v:number)=>125+(v-range.value[0])/(range.value[1]-range.value[0])*425;</script><template><section class="importance-plot"><div class="plot-heading"><h2>封存楼宇的置换解释</h2><span>ΔMAE / kWh</span></div><svg v-if="findings.length" :viewBox="`0 0 590 ${sorted.length*38+63}`" role="img" aria-label="各特征置换后MAE变化与重复分位范围"><line :x1="sx(0)" :x2="sx(0)" y1="12" :y2="sorted.length*38+20" class="zero-line"/><g v-for="(f,i) in sorted" :key="f.id"><text x="109" :y="i*38+30" text-anchor="end" class="feature-label">{{shortNames[f.feature]}}</text><line :x1="sx(0)" :x2="sx(f.importance_mean)" :y1="i*38+26" :y2="i*38+26" class="importance-bar" :class="{negative:f.importance_mean<0}"/><line :x1="sx(f.importance_low)" :x2="sx(f.importance_high)" :y1="i*38+26" :y2="i*38+26" class="repeat-range"/><circle :cx="sx(f.importance_mean)" :cy="i*38+26" r="3" class="mean-dot"/><text x="570" :y="i*38+30" text-anchor="end" class="importance-number">{{number(f.importance_mean,2)}}</text></g><text :x="sx(0)" :y="sorted.length*38+43" text-anchor="middle" class="axis-label">0</text><text x="550" :y="sorted.length*38+43" text-anchor="end" class="axis-label">置换后误差增加 →</text></svg><p v-else class="muted">先完成分组模型研究，读取封存楼宇的重复置换分布。</p><p class="plot-note">线段为重复置换的2.5–97.5%分位范围；负值原样保留。这是模型依赖线索，不是因果节能量。</p></section></template>
